/* Compact render-only network states. Authoritative simulation keeps full precision. */
(function(root){'use strict';
const entityFields=['id','kind','team','x','y','r','hp','max','armor','role','vehicle','vision','range','angle','turret','guns','number','lane','repairVisual','stunnedUntil','flaresUntil','fireTime','fireAmmo','fireAngle','revealUntil','sideObjective','elevation'];
const shotFields=['id','createdAt','x','y','r','vx','vy','owner','team','ammo','kind','guiding','pending','autonomous','effectiveRange','travelled','artillery','height'];
function pick(source,keys){const out={};for(const k of keys){let v=source[k];if(v&&typeof v==='object')v=Array.isArray(v)?v.map(x=>({...x})):{...v};if(v!==undefined)out[k]=typeof v==='number'?Math.round(v*(k==='vx'||k==='vy'||k==='angle'||k==='turret'?100000:100))/ (k==='vx'||k==='vy'||k==='angle'||k==='turret'?100000:100):v;}return out;}
function compact(state){const {vision,...out}=state;out.entities=state.entities.map(u=>pick(u,entityFields));out.ruins=state.ruins.map(u=>pick(u,entityFields));out.shots=state.shots.map(u=>pick(u,shotFields));return out;}
function equal(a,b){return a===b||(a!==null&&b!==null&&typeof a==='object'&&typeof b==='object'&&JSON.stringify(a)===JSON.stringify(b));}
function encode(state,previous){const full=compact(state);const packet={...full,wireVersion:1};if(previous){const before=new Map(previous.entities.map(u=>[u.id,u])),ids=new Set();const changes=[];for(const u of full.entities){ids.add(u.id);const old=before.get(u.id);if(!old){changes.push(u);continue;}const patch={id:u.id};let changed=false;for(const k of entityFields){if(!equal(u[k],old[k])){patch[k]=u[k]??null;changed=true;}}if(changed)changes.push(patch);}if(full.entities.map(u=>u.id).join(',')!==previous.entities.map(u=>u.id).join(','))packet.entityOrder=full.entities.map(u=>u.id);delete packet.entities;packet.entityDelta={changes,removed:previous.entities.filter(u=>!ids.has(u.id)).map(u=>u.id)};}if(previous){const old=new Map(previous.shots.map(u=>[u.id,u])),current=new Set(full.shots.map(u=>u.id)),changes=[];for(const u of full.shots){const prev=old.get(u.id);if(!prev){changes.push(u);continue;}const patch={id:u.id};let changed=false;for(const key of shotFields)if(!equal(u[key],prev[key])){patch[key]=u[key]??null;changed=true;}if(changed)changes.push(patch);}delete packet.shots;packet.shotDelta={changes,removed:previous.shots.filter(u=>!current.has(u.id)).map(u=>u.id)};}return {packet,base:full};}
function decode(packet,previous){if(packet.wireVersion!==1)return packet;const out={...packet};if(packet.entityDelta){const entities=new Map((previous?.entities||[]).map(u=>[u.id,u]));for(const id of packet.entityDelta.removed)entities.delete(id);for(const patch of packet.entityDelta.changes)entities.set(patch.id,{...entities.get(patch.id),...patch});out.entities=packet.entityOrder?packet.entityOrder.map(id=>entities.get(id)):[...entities.values()];delete out.entityDelta;delete out.entityOrder;}if(packet.shotDelta){const shots=new Map((previous?.shots||[]).map(s=>[s.id,s]));for(const id of packet.shotDelta.removed)shots.delete(id);for(const patch of packet.shotDelta.changes)shots.set(patch.id,{...shots.get(patch.id),...patch});out.shots=[...shots.values()];delete out.shotDelta;}out.vision=out.entities.filter(u=>u.team===out.me.team&&u.hp>0).map(u=>({id:u.id,x:u.x,y:u.y,r:u.r,vehicle:u.vehicle,vision:u.vision||200})).concat(out.bonusVision||[]);delete out.wireVersion;return out;}
const api={compact,encode,decode};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.FrontlineTransport=api;
})(typeof globalThis!=='undefined'?globalThis:this);
